{"implementation":"def solve(case):
    import math

    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("missing required case fields")

    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list) or not nodes:
        raise ValueError("nodes must be a non-empty list")
    if not isinstance(required_symbols, list) or any(not isinstance(s, str) for s in required_symbols):
        raise ValueError("required_symbols must be a list of strings")

    required = set(required_symbols)
    by_id = {}
    source_order = {}
    roots = []

    for position, node in enumerate(nodes):
        if not isinstance(node, dict):
            raise ValueError("each node must be an object")
        for field in ("id", "parent", "symbol", "depth", "removable", "utility"):
            if field not in node:
                raise ValueError("missing node field")
        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        removable = node["removable"]
        utility = node["utility"]
        if not isinstance(node_id, str) or node_id in by_id:
            raise ValueError("node ids must be unique strings")
        if parent is not None and not isinstance(parent, str):
            raise ValueError("parent must be null or a string")
        if not isinstance(symbol, str):
            raise ValueError("symbol must be a string")
        if isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
            raise ValueError("depth must be a non-negative integer")
        if not isinstance(removable, bool):
            raise ValueError("removable must be boolean")
        if isinstance(utility, bool) or not isinstance(utility, (int, float)) or not math.isfinite(utility):
            raise ValueError("utility must be finite numeric")
        by_id[node_id] = node
        source_order[node_id] = position
        if parent is None:
            roots.append(node_id)

    if len(roots) != 1:
        raise ValueError("tree must have exactly one root")
    root_id = roots[0]
    if by_id[root_id]["depth"] != 0:
        raise ValueError("root depth must be zero")
    for node in nodes:
        parent = node["parent"]
        if parent is not None and parent not in by_id:
            raise ValueError("parent must reference an existing node")
        if parent is not None and node["depth"] != by_id[parent]["depth"] + 1:
            raise ValueError("invalid parent depth")

    children = {node_id: [] for node_id in by_id}
    for node in nodes:
        if node["parent"] is not None:
            children[node["parent"]].append(node["id"])

    reachable = set()
    stack = [root_id]
    while stack:
        node_id = stack.pop()
        if node_id in reachable:
            raise ValueError("tree contains a cycle")
        reachable.add(node_id)
        stack.extend(children[node_id])
    if len(reachable) != len(nodes):
        raise ValueError("tree must be connected")
    if not required.issubset({node["symbol"] for node in nodes}):
        raise ValueError("required symbols are not represented")

    retained = set(by_id)
    removed = []
    candidates = sorted(
        (node for node in nodes if node["removable"]),
        key=lambda node: (-node["depth"], node["id"])
    )
    for node in candidates:
        node_id = node["id"]
        if node_id == root_id or node["symbol"] in required:
            continue
        if any(child in retained for child in children[node_id]):
            continue
        remaining_symbols = {by_id[kept]["symbol"] for kept in retained if kept != node_id}
        if not required.issubset(remaining_symbols):
            continue
        retained.remove(node_id)
        removed.append(node_id)

    return {
        "removed_node_ids": removed,
        "retained_node_ids": sorted(retained)
    }"}
